    const adult = VARIETY3_ADULT_CONTEXTS.find(row => row.caseId === clinicalCase.id)!;
    return {
      caseId: clinicalCase.id,
      questionVariantId: clinicalCase.decisionNodes[0]!.questionVariantId,
