function authoredFinalConsequenceWithoutOutcomeVignette(
  answerChoiceId: string,
  consequenceNarrative: string,
  clinicalRationale: string,
  sourceLabels: string[],
) {
  return {
    answerChoiceId,
    kind: "no_terminal_outcome" as const,
    consequenceNarrative,
    clinicalRationale,
    sourceLabels,
  };
}

